#!/usr/bin/env node
// T4.1.5 AC2 (REVITION-CLI-PLAN.md:3047-3066): the Revition/homebrew-tap formula, generated by the release workflow
// from the release's SHA256SUMS, so `brew install revition/tap/revition` installs exactly the attested standalone
// binary for the machine (Homebrew itself checks each sha256 before installing).
//
//   node scripts/brew-formula.mjs --version 1.2.3 --sums SHA256SUMS --out revition.rb [--base <download base>]
//
// --base defaults to the GitHub Release download of that version; a test may point it at a local file:// folder.
import { readFileSync, writeFileSync } from 'node:fs';
import { parseArgs } from 'node:util';

const TARGETS = [
  ['darwin', 'arm64'],
  ['darwin', 'x64'],
  ['linux', 'arm64'],
  ['linux', 'x64'],
];

/** The formula text for `version`, from SHA256SUMS text; throws when a target is missing or a sum is malformed. */
export function brewFormula({ version, sums, base }) {
  if (!/^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/u.test(version)) throw new Error(`not a semver version: ${version}`);
  const sha = new Map();
  for (const line of sums.split('\n')) {
    const m = /^([0-9a-f]{64})\s+\*?(\S+)$/u.exec(line.trim());
    if (m) sha.set(m[2], m[1]);
  }
  const from = base ?? `https://github.com/Revition/revition-cli/releases/download/v${version}`;
  const block = (os, arch) => {
    const asset = `revition-${os}-${arch}`;
    const sum = sha.get(asset);
    if (!sum) throw new Error(`SHA256SUMS lists no ${asset}`);
    return [
      `    ${arch === 'arm64' ? 'on_arm' : 'on_intel'} do`,
      `      url "${from}/${asset}"`,
      `      sha256 "${sum}"`,
      '    end',
    ].join('\n');
  };
  const section = (os) =>
    [`  ${os === 'darwin' ? 'on_macos' : 'on_linux'} do`, ...TARGETS.filter(([o]) => o === os).map(([o, a]) => block(o, a)), '  end'].join('\n');
  return `# Generated by scripts/brew-formula.mjs in Revition/revition-cli's release workflow. Do not edit by hand.
class Revition < Formula
  desc "Command-line interface for the Revition Context Graph"
  homepage "https://github.com/Revition/revition-cli"
  version "${version}"
  license "Apache-2.0"

${section('darwin')}
${section('linux')}

  def install
    bin.install Dir["revition-*"].first => "revition"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/revition --version")
  end
end
`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const { values } = parseArgs({ options: { version: { type: 'string' }, sums: { type: 'string' }, out: { type: 'string' }, base: { type: 'string' } } });
  if (!values.version || !values.sums || !values.out) {
    process.stderr.write('usage: brew-formula.mjs --version <semver> --sums <SHA256SUMS> --out <file> [--base <url>]\n');
    process.exit(2);
  }
  writeFileSync(values.out, brewFormula({ version: values.version, sums: readFileSync(values.sums, 'utf8'), base: values.base }));
}
